  return h(
    'div',
    { className: 'mdr-empty' },
    h(Icons.doc, { size: 40 }),
    h('h2', null, 'Markdown Reader'),
    h('div', null, '左侧目录树选择文档，或在顶栏输入相对路径。'),
    h('div', { className: 'mdr-tip' }, meta && meta.roots.length ? `工作区：${meta.roots.map((root) => root.name).join(' · ')}` : '尚未打开工作区'),
  )
